using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsRelevantResponse));

        var evaluator = new RelevanceTruthAndCompletenessEvaluator();
        var chatTurn = new ChatTurn(messages, response);

        var results = await evaluator.EvaluateAsync(
            [chatTurn],
            chatClient,
            additionalContext: ["The capital of France is Paris."]);

        foreach (var result in results)
        {
            Assert.IsTrue(
                result.Value.Rating >= EvaluationRating.Good,
                $"Evaluator {result.Key} rated response as {result.Value.Rating}: {result.Value.Reason}");
        }
    }

    [TestMethod]
    public async Task Chat_HandlesFollowUpQuestions()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire."),
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.AddRange(response.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "What are its main benefits?"));

        var followUpResponse = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesFollowUpQuestions));

        var evaluator = new RelevanceTruthAndCompletenessEvaluator();
        var chatTurn = new ChatTurn(messages, followUpResponse);

        var results = await evaluator.EvaluateAsync(
            [chatTurn],
            chatClient);

        foreach (var result in results)
        {
            Assert.IsTrue(
                result.Value.Rating >= EvaluationRating.Acceptable,
                $"Evaluator {result.Key} rated response as {result.Value.Rating}: {result.Value.Reason}");
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(ChatEvaluationTests).Assembly.Location)!,
            "evaluation-report");

        return DiskBasedReportingConfiguration.Create(storageRootPath: path);
    }
}

